const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Alisal Fire location (Santa Barbara County, CA)
  const fireLocation = ee.Geometry.Point([-120.08, 34.51]);
  const aoi = fireLocation.buffer(15000); // ~15 km buffer to capture fire area

  // Date range: October 11-13, 2021
  const startDate = '2021-10-11';
  const endDate = '2021-10-13';

  // Get Sentinel-2 imagery
  let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoi)
    .filterDate(startDate, endDate)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  let size = col.size().getInfo();
  console.log(`Sentinel-2 Images (Oct 11-13, 2021): ${size}`);

  if (size === 0) {
    // Try Landsat 8
    col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(aoi)
      .filterDate(startDate, endDate);
    size = col.size().getInfo();
    console.log(`Landsat 8 Images (fallback): ${size}`);

    if (size === 0) {
      console.log('C1');
      return;
    }
  }

  // Get pre-fire baseline (late September 2021)
  const preFireCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(aoi)
    .filterDate('2021-09-20', '2021-10-05')
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

  if (preFireCol.size().getInfo() === 0) {
    console.log('No pre-fire imagery for comparison');
    console.log('C1');
    return;
  }

  // Calculate NBR (Normalized Burn Ratio) for fire period
  const fireImg = col.median();
  const preFireImg = preFireCol.median();

  // NBR = (NIR - SWIR) / (NIR + SWIR)
  // For Sentinel-2: Band 8a (NIR), Band 12 (SWIR2)
  const nbrFire = fireImg.normalizedDifference(['B8A', 'B12']).rename('NBR');
  const nbrPre = preFireImg.normalizedDifference(['B8A', 'B12']).rename('NBR');

  // dNBR = Pre-fire NBR - Post-fire NBR (positive values indicate burn)
  const dNBR = nbrPre.subtract(nbrFire).rename('dNBR');

  // Burned area threshold: dNBR > 0.27 is considered moderate to high severity burn
  const burnedMask = dNBR.gt(0.27);

  // Count burned pixels
  const pixelArea = fireImg.select('B2').projection().nominalScale().pow(2).divide(1e6); // in km²

  const burnedPixels = burnedMask
    .reduceRegion(
      reducer=ee.Reducer.sum(),
      geometry=aoi,
      scale=20,
      maxPixels=1e9
    )
    .get('constant');

  const burnedPixelsInfo = burnedPixels.getInfo();
  console.log(`Burned pixels detected: ${burnedPixelsInfo}`);

  if (burnedPixelsInfo === null || burnedPixelsInfo === 0) {
    console.log('No significant burned area detected');
    console.log('C2');
    return;
  }

  // Calculate burned area in acres (1 km² = 247.105 acres, pixel = 400 m² = 0.0004 km²)
  const burnedAreaKm2 = burnedPixelsInfo * 0.0004;
  const burnedAreaAcres = burnedAreaKm2 * 247.105;

  console.log(`Burned Area (Oct 11-13, 2021): ${burnedAreaKm2.toFixed(2)} km² = ${burnedAreaAcres.toFixed(0)} acres`);

  // Validate: Alisal Fire was actually ~17,062 acres by Oct 13
  if (burnedAreaAcres < 10000) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
